I need to understand the nut's geometry to design a partial-credit reward. Let me analyze gripper trajectories vs handle positions across the base nut rollouts.

```bash
python3 - <<'EOF'
import json, math
def d(a,b): return math.dist(a,b)
for line in open("rollouts/1.jsonl"):
    r = json.loads(line)
    fs = r.get('final_state') or {}
    tr = r.get('trace') or {}
    pts = tr.get('points') or []
    obj = fs.get('objects',{})
    nut = obj.get('square_nut') or {}
    peg = obj.get('square_peg') or {}
    handle = nut.get('handle_pos'); initp = nut.get('init_pos'); pos = nut.get('pos')
    # min gripper-handle distance over trace
    best = None
    grasp_pts = 0
    for p in pts:
        g = (p.get('grippers') or {}).get('arm0') or {}
        if handle and g.get('pos'):
            dd = d(g['pos'], handle)
            best = dd if best is None else min(best, dd)
        if (g.get('grasping') or []) and 'square_nut' in g['grasping']:
            grasp_pts += 1
    fs_grasp = (fs.get('grippers',{}).get('arm0',{}).get('grasping') or [])
    print(f"seed {r['seed']} rc={r.get('sandbox_rc')} init={initp} final={pos} handle={handle} peg={peg.get('pos')} "
          f"minD_grip_handle={best and round(best,3)} nutLift={pos and round(pos[2]-initp[2],4) if initp else None} "
          f"maxz={nut.get('max_z')} grasp_pts={grasp_pts} fs_grasp={fs_grasp}")
EOF
```

`preset.py` runs my own programs on the practice simulator (charged as an eval) and returns per-seed `log_tail` — that's my way to validate hand-written programs. And I now understand the nut geometry precisely:
- `square_nut` has `pos` (body), `handle_pos` (horizontal handle tip), `init_pos`; the nut is a z-yawed body sitting on the table (z≈0.83), handle points horizontally.
- `square_peg` at [0.23, 0.1, 0.85] is the target; `round_peg` at [0.23, -0.1, 0.85] is a **distractor**.
- Base's gripper never comes within 0.13m of the handle → zero nut signal at all.

Let me write a **dispatch reward**: dense partial-credit for nut (approach / picked-up / lift / align / insert, all measurable from `trace`+`final_state`), stage-fraction for restack. Then test it against the recorded rows before training.

```bash
cat > reward_dispatch.py <<'PY'
import math

def _get(r, key, default=None):
    try:
        if hasattr(r, "get"):
            return r.get(key, default)
    except Exception:
        pass
    try:
        return getattr(r, key, default)
    except Exception:
        return default

def _clip(x, lo, hi):
    return max(lo, min(hi, x))

def _dist(a, b):
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))

def _stages_frac(r):
    stages = _get(r, "stages")
    if not stages:
        return 0.0
    n = sum(1 for v in stages.values() if v)
    k = len(stages)
    val = n / k if k else 0.0
    if _get(r, "task_completed"):
        val = max(val, 1.0)
    return val

def _nut_reward(r):
    fs = _get(r, "final_state")
    tr = _get(r, "trace")
    if not fs or not tr:
        return _stages_frac(r)
    objs = fs.get("objects") or {}
    nut = objs.get("square_nut")
    peg = objs.get("square_peg")
    if not nut or not peg:
        return _stages_frac(r)
    init = nut.get("init_pos"); final = nut.get("pos"); handle = nut.get("handle_pos")
    pegp = peg.get("pos")
    if not init or not final or not handle or not pegp:
        return _stages_frac(r)
    pts = tr.get("points") or []
    min_appr = None
    max_lift = 0.0
    best_xy = 1e9
    for p in pts:
        g = (p.get("grippers") or {}).get("arm0") or {}
        gp = g.get("pos")
        if gp:
            d = _dist(gp, handle)
            d2 = _dist(gp, init)  # near body counts too (handle may be hidden)
            d = min(d, d2)
            if min_appr is None or d < min_appr:
                min_appr = d
        on = (p.get("objects") or {}).get("square_nut") or {}
        op = on.get("pos")
        if op:
            lift = op[2] - init[2]
            if lift > max_lift:
                max_lift = lift
            dxy = math.hypot(op[0] - pegp[0], op[1] - pegp[1])
            if dxy < best_xy:
                best_xy = dxy
    # fold in final state
    dxyf = math.hypot(final[0] - pegp[0], final[1] - pegp[1])
    if dxyf < best_xy:
        best_xy = dxyf
    liftf = final[2] - init[2]
    if liftf > max_lift:
        max_lift = liftf
    approach = _clip(1 - (min_appr - 0.04) / (0.12 - 0.04), 0, 1) if min_appr is not None else 0.0
    held_lift = max_lift > 0.03
    lift_f = _clip((max_lift - 0.02) / 0.06, 0, 1)
    align = _clip(1 - (best_xy - 0.03) / (0.12 - 0.03), 0, 1)
    znear = _clip(1 - abs(final[2] - pegp[2]) / 0.06, 0, 1)
    insert = align * znear
    score = 0.20 * approach
    if held_lift:
        score += 0.15 + 0.15 * lift_f + 0.25 * align + 0.25 * insert
    if _get(r, "task_completed"):
        score = max(score, 1.0)
    return _clip(score, 0, 1)

def reward(r):
    rc = _get(r, "sandbox_rc")
    if rc is not None and rc != 0:
        return 0.0
    t = _get(r, "task")
    if t == "nut":
        try:
            return _nut_reward(r)
        except Exception:
            return _stages_frac(r)
    return _stages_frac(r)
PY
python3 -c "import ast; ast.parse(open('reward_dispatch.py').read()); print('parses ok')"
python3 - <<'EOF'
import json, importlib.util
spec = importlib.util.spec_from_file_location("rd", "reward_dispatch.py")
rd = importlib.util.module_from_spec(spec); spec.loader.exec_module(rd)
print("=== NUT rows (job1) reward values ===")
for line in open("rollouts/1.jsonl"):
    r=json.loads(line)
    print(f"  seed {r['seed']} rc={r.get('sandbox_rc')} -> {rd.reward(r):.3f}")
print("=== RESTACK rows (job2) reward values ===")
for line in open("rollouts/2.jsonl"):
    r=json.loads(line)
    print(f"  seed {r['seed']} rc={r.get('sandbox_rc')} -> {rd.reward(r):.3f}")
EOF
